<?php
declare(strict_types=1);

namespace wise\agent\schema\generator;

use wise\agent\schema\dto\FieldInfo;
use wise\agent\schema\dto\PluginSchemaDTO;
use wise\agent\schema\dto\TableInfo;
use wise\agent\schema\params\ParamBuilder;
use wise\agent\schema\security\SecurityGuard;

/**
 * AI Tool 自动生成器（协调器）
 *
 * 根据 PluginSchemaDTO 和安全守卫自动生成所有标准 AI Tool。
 * 核心职责：
 *   - 分析每张表的特征（字段类型、关系、是否有数值字段等）
 *   - 决定生成哪些工具类型
 *   - 调用 ParamBuilder 构建工具参数
 *   - 创建 AutoGeneratedTool 实例
 *   - 统一注册到 ToolRegistry
 *
 * 生成策略：
 *   | 工具类型          | 命名格式                           | 生成条件                |
 *   |-------------------|------------------------------------|-------------------------|
 *   | list              | {plugin}_list_{table}              | 始终生成                |
 *   | get               | {plugin}_get_{table}               | 始终生成                |
 *   | search            | {plugin}_search_{table}            | 有 string 字段时生成    |
 *   | stats             | {plugin}_stats_{table}             | 有 numeric 字段时生成   |
 *   | create            | {plugin}_create_{table}            | 有可写字段时生成        |
 *   | update            | {plugin}_update_{table}            | 有可写字段时生成        |
 *   | delete            | {plugin}_delete_{table}            | 有可写字段时生成        |
 *   | list_with_relation| {plugin}_list_{table}_with_{rel}   | 有 relations 时生成     |
 *
 * 使用示例：
 *   $schema = $introspector->introspect('smartstock');
 *   $guard = SecurityGuard::fromSchema($schema);
 *   $guard->setWritableFields('smartstock_product', ['name', 'selling_price']);
 *
 *   $generator = new AiToolGenerator($schema, $guard);
 *   $tools = $generator->generate();
 *
 *   // 注册到 ToolRegistry
 *   $generator->registerTo(ToolRegistry::instance());
 */
class AiToolGenerator
{
    /** @var PluginSchemaDTO 插件 Schema */
    private $schema;

    /** @var SecurityGuard 安全守卫 */
    private $guard;

    /** @var AutoGeneratedTool[] 已生成的工具列表 */
    private $generatedTools = [];

    /** @var array<string, int|array> 生成统计 */
    private $stats = [
        'tables_scanned'    => 0,
        'tools_generated'   => 0,
        'tools_skipped'     => 0,
        'by_type'           => [],
    ];

    /**
     * @param PluginSchemaDTO $schema 插件 Schema
     * @param SecurityGuard $guard 安全守卫
     */
    public function __construct(PluginSchemaDTO $schema, SecurityGuard $guard)
    {
        $this->schema = $schema;
        $this->guard  = $guard;
    }


    /**
     * 为所有允许的表生成 AI Tools
     *
     * @return AutoGeneratedTool[] 生成的工具列表
     */
    public function generate(): array
    {
        $this->generatedTools = [];

        foreach ($this->schema->tables as $table) {
            if (!($table instanceof TableInfo)) {
                continue;
            }

            if (!$this->guard->isTableAllowed($table->name)) {
                $this->stats['tools_skipped']++;
                continue;
            }

            $this->stats['tables_scanned']++;

            $tableTools = $this->generateForTable($table);
            foreach ($tableTools as $tool) {
                $this->generatedTools[] = $tool;
            }
        }

        $this->stats['tools_generated'] = count($this->generatedTools);

        return $this->generatedTools;
    }

    /**
     * 注册所有已生成的工具到 ToolRegistry
     *
     * @param \wise\agent\tool\ToolRegistry $registry
     * @return int 注册的工具数量
     */
    public function registerTo($registry): int
    {
        if (empty($this->generatedTools)) {
            $this->generate();
        }

        $count = 0;
        $namespace = 'plugin:' . $this->schema->pluginIdent;

        foreach ($this->generatedTools as $tool) {
            $registry->register($tool, $tool->getName(), $namespace);
            $count++;
        }

        return $count;
    }

    /**
     * 获取生成统计
     *
     * @return array
     */
    public function getStats(): array
    {
        return $this->stats;
    }

    /**
     * 获取已生成的工具列表
     *
     * @return AutoGeneratedTool[]
     */
    public function getGeneratedTools(): array
    {
        return $this->generatedTools;
    }


    /**
     * 为单张表生成所有适用的工具
     *
     * @param TableInfo $table
     * @return AutoGeneratedTool[]
     */
    private function generateForTable(TableInfo $table): array
    {
        $tools = [];
        $builder = new ParamBuilder($this->schema->pluginIdent, $table);

        $tools[] = $this->makeListTool($table, $builder);

        $tools[] = $this->makeGetTool($table, $builder);

        if ($this->hasSearchableFields($table)) {
            $tools[] = $this->makeSearchTool($table, $builder);
        } else {
            $this->incrementSkip('search');
        }

        if ($this->hasNumericFields($table)) {
            $tools[] = $this->makeStatsTool($table, $builder);
        } else {
            $this->incrementSkip('stats');
        }

        $writableFields = $this->getWritableFields($table);
        if (!empty($writableFields)) {
            $tools[] = $this->makeCreateTool($table, $builder, $writableFields);
        } else {
            $this->incrementSkip('create');
        }

        if (!empty($writableFields)) {
            $tools[] = $this->makeUpdateTool($table, $builder, $writableFields);
        } else {
            $this->incrementSkip('update');
        }

        $tools[] = $this->makeDeleteTool($table, $builder);

        if (!empty($table->relations)) {
            foreach ($table->relations as $relation) {
                if (method_exists($relation, 'getName') || isset($relation->name)) {
                    $relName = method_exists($relation, 'getName')
                        ? $relation->getName()
                        : $relation->name;
                } else {
                    $relName = $relation->name ?? '';
                }
                if (!empty($relName)) {
                    $tools[] = $this->makeListWithRelationTool($table, $builder, $relName);
                }
            }
        } else {
            $this->incrementSkip('list_with_relation');
        }

        foreach ($tools as $tool) {
            $type = $tool->getToolType();
            if (!isset($this->stats['by_type'][$type])) {
                $this->stats['by_type'][$type] = 0;
            }
            $this->stats['by_type'][$type]++;
        }

        return $tools;
    }


    /**
     * 创建列表查询工具
     */
    private function makeListTool(TableInfo $table, ParamBuilder $builder): AutoGeneratedTool
    {
        $filterFields = $this->getFilterableFields($table);

        $params = $builder->forList()
            ->addPagination()
            ->addSorting()
            ->addFieldFilters($filterFields)
            ->build();

        $desc = $this->buildDescription('list', $table);

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'list',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建单条查询工具
     */
    private function makeGetTool(TableInfo $table, ParamBuilder $builder): AutoGeneratedTool
    {
        $params = $builder->forGet()
            ->addPrimaryKey()
            ->build();

        $desc = $this->buildDescription('get', $table);

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'get',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建搜索工具
     */
    private function makeSearchTool(TableInfo $table, ParamBuilder $builder): AutoGeneratedTool
    {
        $filterFields = $this->getFilterableFields($table);

        $params = $builder->forSearch()
            ->addSearchKeyword()
            ->addPagination()
            ->addFieldFilters($filterFields)
            ->build();

        $desc = $this->buildDescription('search', $table);

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'search',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建统计工具
     */
    private function makeStatsTool(TableInfo $table, ParamBuilder $builder): AutoGeneratedTool
    {
        $hasNumeric = $this->hasNumericFields($table);
        $filterFields = $this->getFilterableFields($table);

        $params = $builder->forStats()
            ->addStatType($hasNumeric)
            ->addFieldFilters($filterFields)
            ->build();

        $desc = $this->buildDescription('stats', $table);

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'stats',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建记录工具
     */
    private function makeCreateTool(TableInfo $table, ParamBuilder $builder, array $writableFields): AutoGeneratedTool
    {
        $params = $builder->forCreate()
            ->addWritableFields($writableFields, true)
            ->build();

        $desc = $this->buildDescription('create', $table);

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'create',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建更新工具
     */
    private function makeUpdateTool(TableInfo $table, ParamBuilder $builder, array $writableFields): AutoGeneratedTool
    {
        $params = $builder->forUpdate()
            ->addPrimaryKey()
            ->addWritableFields($writableFields, false)
            ->build();

        $desc = $this->buildDescription('update', $table);

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'update',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建删除工具
     */
    private function makeDeleteTool(TableInfo $table, ParamBuilder $builder): AutoGeneratedTool
    {
        $params = $builder->forDelete()
            ->addPrimaryKey()
            ->build();

        $deleteMode = $table->hasSoftDelete ? '软删除' : '硬删除';
        $desc = $this->buildDescription('delete', $table) . '（' . $deleteMode . '）';

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'delete',
            $this->guard,
            $this->schema->pluginIdent
        );
    }

    /**
     * 创建关联查询工具
     */
    private function makeListWithRelationTool(TableInfo $table, ParamBuilder $builder, string $relationName): AutoGeneratedTool
    {
        $filterFields = $this->getFilterableFields($table);

        $params = $builder->forListWithRelation($relationName)
            ->addPagination()
            ->addSorting()
            ->addFieldFilters($filterFields)
            ->build();

        $desc = '查询 ' . $this->tableLabel($table) . ' 列表（含关联的 ' . $relationName . ' 信息）';

        return new AutoGeneratedTool(
            $params->toolName,
            $desc,
            $params,
            $table,
            'list_with_relation',
            $this->guard,
            $this->schema->pluginIdent
        );
    }


    /**
     * 构建工具描述
     *
     * @param string $toolType
     * @param TableInfo $table
     * @return string
     */
    private function buildDescription(string $toolType, TableInfo $table): string
    {
        $label = $this->tableLabel($table);

        $descriptions = [
            'list'   => '查询' . $label . '列表。支持分页、排序和条件过滤。',
            'get'    => '按主键查询单条' . $label . '记录。',
            'search' => '按关键词搜索' . $label . '。在可搜索字段中模糊匹配。',
            'stats'  => $label . '数据统计分析。支持计数、数值汇总、分组统计。',
            'create' => '创建新的' . $label . '记录。',
            'update' => '更新' . $label . '记录（按主键）。',
            'delete' => '删除' . $label . '记录',
        ];

        return isset($descriptions[$toolType]) ? $descriptions[$toolType] : $label . ' - ' . $toolType;
    }

    /**
     * 获取表的友好标签
     *
     * @param TableInfo $table
     * @return string
     */
    private function tableLabel(TableInfo $table): string
    {
        if (!empty($table->comment)) {
            return $table->comment;
        }
        return '表 `' . $table->name . '`';
    }

    /**
     * 获取可过滤的字段名列表
     *
     * @param TableInfo $table
     * @return string[]
     */
    private function getFilterableFields(TableInfo $table): array
    {
        $filterable = [];

        foreach ($table->fields as $field) {
            if (!($field instanceof FieldInfo)) {
                continue;
            }

            if ($field->isPrimary && $field->isAutoIncrement) {
                continue;
            }
            if (in_array($field->type, ['text', 'json'], true)) {
                continue;
            }

            $filterable[] = $field->name;
        }

        return $filterable;
    }

    /**
     * 获取可写字段列表
     *
     * @param TableInfo $table
     * @return FieldInfo[]
     */
    private function getWritableFields(TableInfo $table): array
    {
        return $this->guard->filterWritableFields($table->name, $table->fields);
    }

    /**
     * 检查表是否有可搜索字段
     *
     * @param TableInfo $table
     * @return bool
     */
    private function hasSearchableFields(TableInfo $table): bool
    {
        return !empty($table->getSearchableFields());
    }

    /**
     * 检查表是否有数值字段
     *
     * @param TableInfo $table
     * @return bool
     */
    private function hasNumericFields(TableInfo $table): bool
    {
        return !empty($table->getNumericFields());
    }

    /**
     * 增加跳过计数
     *
     * @param string $toolType
     */
    private function incrementSkip(string $toolType): void
    {
        $this->stats['tools_skipped']++;
    }
}
